// episodeId from a Stremio id: 'series:<slug>:<epId>' | '<slug>:<epId>' | '<slug>'
async function episodeIdFor(type, id) {
  const parts = String(id || '').split(':');
  if (parts.length >= 2 && /^\d+$/.test(parts[parts.length - 1])) return parts[parts.length - 1];
  const slug = parts[parts.length - 1];
  if (!slug) return null;
  try {
    if (type === 'movie') {
      const m = await getMovieMeta(slug);
      return (m && m.movieEpisodeId) || null;
    }
    const m = await getSeriesMeta(slug);
    const v = (m && m.videos) || [];
    if (!v.length) return null;
    return v[0].episodeId || String(v[0].id).split(':').pop();
  } catch (e) { return null; }
}


// ---- genres: the site's categories + OUR derived tags --------------------
// Our tags come from build-ours.js (Arabic title + synopsis + year + the site's
// hand-curated collections). Options are merged by normalised label: where our
// tag and a site category share a name (e.g. 'أكشن'), one option matches BOTH.
// Only these of the site's own categories are surfaced as filters (owner's pick):
// جييم, سبيستون (+ إصدارات سبيستون), سبيس باور, mbc3. The rest stay in the data
// (they still boost our derived tags) but are not offered as separate options.
const SITE_KEEP = ['mbc3', 'sbyston', 'asdarat-sbyston', 'sbys-baor', 'aflam-gyym-jeem'];
function siteGenreLabels() {
  const all = (((INDEX.genres || {}).labels) || []);
  return all.filter(([slug]) => SITE_KEEP.indexOf(slug) >= 0);
}
function ourGenreLabels() { return (((INDEX.ourGenres || {}).labels) || []); }

let _gmap = null;
function genreMap() {
  if (_gmap) return _gmap;
  const ours = ourGenreLabels();
  const allSite = (((INDEX.genres || {}).labels) || []);
  const site = allSite
    .map(([slug, label], i) => [slug, label, i])
    .filter(([slug]) => SITE_KEEP.indexOf(slug) >= 0);
  const options = [], sources = {}, usedSite = new Set();
  for (let i = 0; i < ours.length; i++) {
    const label = ours[i], n = normTitle(label);
    const list = [{ kind: 'our', i }];
    for (const [slug, slabel, sIdx] of site) {
      if (normTitle(slabel) === n) { list.push({ kind: 'site', i: sIdx }); usedSite.add(sIdx); }
    }
    options.push(label); sources[label] = list;
  }
  for (const [slug, slabel, sIdx] of site) {
    if (usedSite.has(sIdx)) continue;
    if (options.indexOf(slabel) >= 0) continue;
    options.push(slabel); sources[slabel] = [{ kind: 'site', i: sIdx }];
  }
  _gmap = { options, sources };
  return _gmap;
}
function genreOptions() { return genreMap().options; }

function genreBreakdown(slug) {
  const out = [];
  const seen = new Set();
  const add = (l) => { const n = normTitle(l); if (l && !seen.has(n)) { seen.add(n); out.push(l); } };
  const ourIdx = (((INDEX.ourGenres || {}).items) || {})[slug];
  if (ourIdx) for (const n of String(ourIdx).split(',')) add(ourGenreLabels()[+n]);
  const siteIdx = (((INDEX.genres || {}).items) || {})[slug];
  if (siteIdx) for (const n of String(siteIdx).split(',')) add((siteGenreLabels()[+n] || [])[1]);
  return out;
}
function genreMatches(slug, wanted) {
  const w = String(wanted || '').trim();
  if (!w) return true;
  const gm = genreMap();
  const nw = normTitle(w);
  let label = gm.options.indexOf(w) >= 0 ? w
    : gm.options.find((o) => normTitle(o) === nw)
    || gm.options.find((o) => normTitle(o).indexOf(nw) >= 0);
  if (!label) return false;
  for (const src of (gm.sources[label] || [])) {
    const table = src.kind === 'our' ? (INDEX.ourGenres || {}) : (INDEX.genres || {});
    const raw = (table.items || {})[slug];
    if (!raw) continue;
    if ((',' + String(raw) + ',').indexOf(',' + src.i + ',') >= 0) return true;
  }
  return false;
}

// ---- alphabetical catalog (embedded index + live newest pages) ------------
const _cache = new Map();
const FRESH_TTL = 15 * 60 * 1000; // 15 min

async function fetchNewest(ep) {
  const hit = _cache.get('fresh:' + ep);
  if (hit && Date.now() - hit.t < FRESH_TTL) return hit.v;
  const out = [];
  for (const p of [1, 2, 3]) {
    try {
      const j = await getJson(`${BASE}/${ep}?page=${p}`);
      (j.videos || []).forEach(v => {
        const slug = slugFromUrl(v.url);
        if (slug) out.push([slug, (v.title || '').trim(), compactPoster(v.poster_url || v.poster), String(v.year || '')]);
      });
    } catch (e) { /* keep whatever we got */ }
    await sleep(80);
  }
  if (out.length) _cache.set('fresh:' + ep, { t: Date.now(), v: out });
  return out.length ? out : (hit ? hit.v : []);
}

// ---- search: live site results + instant match on the embedded index -----
let _rows = null;
function indexRows() {
  if (_rows) return _rows;
  _rows = [];
  for (const key of ['series', 'movies']) {
    const type = key === 'movies' ? 'movie' : 'series';
    for (const it of ((INDEX[key] || {}).items) || []) {
      _rows.push({ type, slug: it[0], title: it[1], poster: it[2], year: it[3], n: normTitle(it[1]) });
    }
  }
  return _rows;
}
function searchIndex(q) {
  const nq = normTitle(q);
  if (nq.length < 2) return [];
  const out = [];
  for (const r of indexRows()) {
    const i = r.n.indexOf(nq);
    if (i < 0) continue;
    out.push({ id: r.type + ':' + r.slug, type: r.type, slug: r.slug, title: r.title,
      poster: decodePoster(r.poster) || undefined, year: r.year || undefined });
  }
  return out;
}
// Site results win when both know a title; the index adds everything the site
// search misses (odd spellings, long-tail titles, or the site being down).
function mergeSearch(site, q) {
  const out = new Map();
  for (const x of site || []) {
    const type = x.type || 'series';
    out.set(type + ':' + (x.slug || x.id), { ...x, type });
  }
  for (const x of searchIndex(q)) if (!out.has(x.id)) out.set(x.id, x);
  const nq = normTitle(q);
  const arr = [...out.values()];
  for (const x of arr) x.q = normTitle(x.title).startsWith(nq) ? 0 : 1; // prefix hits first
  arr.sort((a, b) => a.q - b.q || byTitleAr(a.title, b.title));
  return arr.slice(0, 150);
}

async function newestShelf(key) {
  const items = await fetchNewest(epOfKey(key));
  const seen = new Set(); const out = [];
  for (const it of items) { if (seen.has(it[0])) continue; seen.add(it[0]); out.push(it); }
  return out;
}

async function sortedItems(key) {
  const ck = 'sorted:' + key;
  const hit = _cache.get(ck);
  if (hit && Date.now() - hit.t < FRESH_TTL) return hit.v;
  const base = ((INDEX[key] || {}).items) || [];
  const map = new Map();
  for (const it of base) map.set(it[0], it);
  for (const it of await fetchNewest(epOfKey(key))) map.set(it[0], it); // newest wins
  const arr = [...map.values()].sort((a, b) => byTitleAr(a[1], b[1]));
  _cache.set(ck, { t: Date.now(), v: arr });
  return arr;
}

function chunkCount(key) {
  const n = (((INDEX[key] || {}).items) || []).length;
  return Math.max(1, Math.ceil(n / CHUNK_SIZE));
}

// ---- manifest -------------------------------------------------------------
function buildManifest(url) {
  const mode = catalogMode(url);
  const arabicNum = (n) => String(n).replace(/\d/g, d => '٠١٢٣٤٥٦٧٨٩'[d]);
  const searchExtra = [{ name: 'search', isRequired: false }];
  const series = [], movies = [];
  if (mode === 'single') {
    const genreExtra = genreOptions().length
      ? [{ name: 'genre', options: genreOptions(), isRequired: false }] : [];
    series.push({ id: 'stardima-new', type: 'series', name: `${NAME}: أحدث المسلسلات`, extra: searchExtra });
    series.push({ id: 'stardima', type: 'series', name: `${NAME}: مسلسلات (أ-ي)`, extra: [...genreExtra, ...searchExtra] });
    movies.push({ id: 'stardima-new-movies', type: 'movie', name: `${NAME}: أحدث الأفلام`, extra: searchExtra });
    movies.push({ id: 'stardima-movies', type: 'movie', name: `${NAME}: أفلام (أ-ي)`, extra: [...genreExtra, ...searchExtra] });
  } else {
    const sChunks = chunkCount('series'), mChunks = chunkCount('movies');
    for (let c = 1; c <= sChunks; c++) series.push({
      id: 'stardima-s' + c, type: 'series',
      name: c === 1 ? `${NAME}: مسلسلات` : `${NAME}: مسلسلات (${arabicNum(c)})`,
      extra: searchExtra,
    });
    for (let c = 1; c <= mChunks; c++) movies.push({
      id: 'stardima-m' + c, type: 'movie',
      name: c === 1 ? `${NAME}: أفلام` : `${NAME}: أفلام (${arabicNum(c)})`,
      extra: searchExtra,
    });
  }
  const sN = (((INDEX.series || {}).items) || []).length;
  const mN = (((INDEX.movies || {}).items) || []).length;
  return {
    id: ID, version: VERSION, name: `${NAME} — ستارديما (أ-ي)`,
    description: 'مكتبة ستارديما كاملة مرتبة أبجديًا: ' + sN + ' مسلسل و' + mN + ' فيلم، مع حلقات وبث مباشر',
    resources: ['catalog', 'meta', 'stream'], types: ['series', 'movie'],
    idPrefixes: ['stardima:'], catalogs: [...series, ...movies],
    behaviorHints: { configurableFor: false, configurationRequired: false },
  };
}

// ---- self-check + alerting (cron) ----------------------------------------
// Workers cron triggers run this on a schedule. On failure we push a message to
// ntfy.sh (free, no account) so the owner gets told *before* users complain.
const ALERT_TOPIC = 'stardima-alerts-7k2p9q4x'; // ntfy fallback (blocked from CF, kept for non-CF callers)
const GH_REPO = 'Albrall/stardima-addon';
// Alerts go to a GitHub issue (which emails the repo owner). Workers cron, the
// opportunistic timer below, or /alert-test all use this path.
async function alertIssue(title, body, env) {
  const token = (env && env.ALERT_GH_TOKEN) || (_env && _env.ALERT_GH_TOKEN);
  if (!token) return { ok: false, error: 'no ALERT_GH_TOKEN secret' };
  const H = { Authorization: 'token ' + token, Accept: 'application/vnd.github+json', 'User-Agent': 'stardima-addon' };
  try {
    const q = await fetch(`https://api.github.com/repos/${GH_REPO}/issues?state=open&labels=alert&per_page=1`, { headers: H });
    const open = await q.json();
    if (Array.isArray(open) && open.length) {
      const r = await fetch(open[0].comments_url, { method: 'POST', headers: H, body: JSON.stringify({ body }) });
      return { ok: r.ok, status: r.status, updated: open[0].number };
    }
    const r = await fetch(`https://api.github.com/repos/${GH_REPO}/issues`, {
      method: 'POST', headers: H,
      body: JSON.stringify({ title, body, labels: ['alert'] }),
    });
    const j = await r.json();
    return { ok: r.ok, status: r.status, issue: j.number, url: j.html_url };
  } catch (e) { return { ok: false, error: String((e && e.message) || e) }; }
}
async function alertPush(title, message, ok, env) {
  const viaIssue = await alertIssue(title, message, env);
  if (viaIssue && viaIssue.ok) return viaIssue;
  try {
    const r = await fetch('https://ntfy.sh/' + ALERT_TOPIC, {
      method: 'POST',
      headers: { Title: encodeURIComponent(title), Priority: ok ? '3' : '5', Tags: ok ? 'white_check_mark' : 'warning' },
      body: message,
    });
    return { status: r.status, ok: r.ok };
  } catch (e) { return { status: 0, ok: false, error: String((e && e.message) || e) }; }
}

async function selfCheck() {
  const out = { at: new Date().toISOString(), checks: {} };
  let ok = true;
  // 1) upstream site
  try {
    const j = await getJson(BASE + '/mosalsalat?page=1');
    out.checks.site = { ok: ((j.videos) || []).length > 0, rows: ((j.videos) || []).length };
  } catch (e) { out.checks.site = { ok: false, error: String((e && e.message) || e).slice(0, 100) }; }
  // 2) catalog from the embedded index
  try {
    const arr = await sortedItems('series');
    out.checks.catalog = { ok: arr.length > 1000, items: arr.length };
  } catch (e) { out.checks.catalog = { ok: false, error: String(e.message).slice(0, 100) }; }
  // 3) full playback chain on a known episode (resolve -> playlist -> segment)
  try {
    const servers = await getServers('1445');
    const list = await orderServers((servers && servers.servers) || [], { probe: false });
    let play = { ok: false };
    for (const srv of list.slice(0, 3)) {
      const r = await resolveHost(srv.embedUrl);
      if (!r || !r.url) continue;
      const hdr = { 'User-Agent': UA, Referer: r.referer, Accept: '*/*' };
      const nonTag = (t) => String(t).split(/\r?\n/).find((l) => l && !l.startsWith('#'));
      const up = await fetchT(r.url, { headers: hdr }, 15000);
      if (!up.ok) continue;
      if (r.type !== 'hls') { play = { ok: true, host: srv.name, type: r.type }; break; }
      const vurl = new URL(nonTag(await up.text()), r.url).href;
      const vu = await fetchT(vurl, { headers: hdr }, 15000);
      if (!vu.ok) continue;
      const surl = new URL(nonTag(await vu.text()), vurl).href;
      const su = await fetchT(surl, { headers: { ...hdr, Range: 'bytes=0-1000' } }, 20000);
      play = { ok: !!su.ok, host: srv.name, type: r.type, segment: su.status };
      if (su.ok) break;
    }
    out.checks.playback = play;
  } catch (e) { out.checks.playback = { ok: false, error: String(e.message).slice(0, 100) }; }
  for (const v of Object.values(out.checks)) if (!v.ok) ok = false;
  out.ok = ok;
  return out;
}

